import { OfferType } from '@prisma/client';

/**
 * Module 14 Phase 3B — the Pairley marketing copy catalog.
 *
 * This is the copy that explains *how Pairley works* for a given offer type.
 * It is deliberately NOT generated by a model. Every string here is a pure
 * function of `offer_type` and `required_people` — nothing about the specific
 * merchant, dish, or price — which is exactly why it can be a fixed catalog:
 *
 *  - **Zero hallucination.** The rule "never promise that a group will form"
 *    holds because no code path can emit a promise, not because a prompt
 *    asked a model to behave and we hoped it complied on every generation.
 *  - **Zero token cost** on the path that renders a banner.
 *  - **One review.** Approve the BOGO wording once; every BOGO offer on
 *    Pairley says exactly that, forever.
 *  - **Localizable.** Entries are strings with `{{placeholders}}`, not
 *    functions, so a translator can work from a plain string table. Adding
 *    Tamil/Kannada/Telugu/Hindi is a new key in CATALOG, no code change.
 *
 * What a model *may* rewrite is the merchant's own title/description/summary
 * into house style — that lives elsewhere and is always admin-reviewed.
 * Nothing in this file is ever model output.
 *
 * ---
 * WORDING RULE, load-bearing: copy must describe the *condition*
 * ("once the required number of customers show interest…"), never the
 * *outcome* ("we'll find you a partner", "your group will fill"). Pairley
 * cannot promise that a group forms. Any new entry must follow this.
 */

export type Locale = 'en';

export const DEFAULT_LOCALE: Locale = 'en';

export interface CopyStrings {
  /** Short line for the banner. */
  headline: string;
  /** The Pairley explanation shown under the offer. */
  body: string;
  /** Used instead when the offer needs no group (required_people <= 1). */
  soloHeadline?: string;
  soloBody?: string;
}

export interface CopyContext {
  requiredPeople?: number | null;
  locale?: Locale;
}

export interface RenderedCopy {
  headline: string;
  body: string;
  /** Which catalog entry produced this — persisted on the offer so wording
   *  fixes apply retroactively without rewriting stored copy. */
  templateKey: string;
  groupRequired: boolean;
}

