const CATALOG: Record<Locale, Record<OfferType, CopyStrings>> = {
  en: EN,
};

/**
 * `{{people}}` interpolates to the *number only* — each template supplies
 * its own noun ("{{people}} customers", "{{people}} members"), because the
 * right noun differs per offer type and, more importantly, differs per
 * language once this catalog is translated. A placeholder that expanded to
 * "12 people" would produce "12 people customers" wherever a template
 * already had a noun.
 */
function interpolate(template: string, people: number): string {
  return template.replace(/\{\{people\}\}/g, String(people));
}

/**
 * The one entry point. Given an offer type and how many participants it
 * needs, returns the approved Pairley explanation.
 *
 * An unknown offer type falls back to STANDARD rather than throwing —
 * copy is presentation, and a customer seeing generic-but-accurate wording
 * is far better than an offer page that fails to render.
 */
export function renderPairleyCopy(
  offerType: string,
  context: CopyContext = {},
): RenderedCopy {
  const locale = context.locale ?? DEFAULT_LOCALE;
  const table = CATALOG[locale] ?? CATALOG[DEFAULT_LOCALE];

  const key =
    (offerType as OfferType) in table
      ? (offerType as OfferType)
      : OfferType.STANDARD;
  const entry = table[key];

  const requiredPeople = Number(context.requiredPeople ?? 0);
  const groupRequired = Number.isFinite(requiredPeople) && requiredPeople > 1;

  if (!groupRequired && entry.soloBody) {
    return {
      headline: entry.soloHeadline ?? entry.headline,
      body: entry.soloBody,
      templateKey: `${key}_SOLO`,
      groupRequired: false,
    };
  }

  // Group wording with no real group size would read "once 0 people…".
  const people = groupRequired ? requiredPeople : 2;

  return {
    headline: entry.headline,
    body: interpolate(entry.body, people),
    templateKey: key,
    groupRequired,
  };
}

/** Every locale/offer-type pair, for review and translation workflows. */
export function getCopyCatalog(locale: Locale = DEFAULT_LOCALE) {
  const table = CATALOG[locale] ?? CATALOG[DEFAULT_LOCALE];
  return Object.entries(table).map(([offerType, strings]) => ({
    offerType,
    ...strings,
  }));
}

export function getSupportedLocales(): Locale[] {
  return Object.keys(CATALOG) as Locale[];
}
